 private selectFeature(recordId:string,start:number,end:number){
  const record=this.state.records.find(r=>r.id===recordId);if(!record)return;let candidates:{state:ProteinState;positions:number[]}[]=[];
  if(record.molecule==='protein')candidates=this.state.states.filter(s=>s.sequence===record.sequence&&s.operation.kind!=='sequence-variant').map(state=>({state,positions:Array.from({length:end-start},(_,i)=>start+i)}));
  else for(const coding of this.state.codingSources.filter(c=>c.recordId===recordId)){const state=this.state.states.find(s=>s.id===coding.proteinStateId)!;const positions=coding.codonPositions.map((p,i)=>p.some(n=>n>=start&&n<end)?i:-1).filter(i=>i>=0&&i<state.sequence.length);if(positions.length)candidates.push({state,positions});}
  const current=candidates.find(c=>c.state.id===this.state.activeStateId),chosen=current??(candidates.length===1?candidates[0]:null);if(!chosen)throw new Error('Select the matching source protein state first. A feature does not establish correspondence to an edited or ambiguous protein.');
  this.state={...this.state,activeStateId:chosen.state.id};this.selectedFeatureIds=new Set(chosen.positions.map(i=>chosen.state.residueIds[i]));this.selected=chosen.positions[0];this.page=Math.floor(this.selected/100);this.services.changed();this.render();
  const binding=this.services.getStructure(),mapping=this.state.mappings.findLast(m=>m.reviewed&&m.proteinStateId===chosen.state.id&&m.sourceSha256===binding?.sourceSha256&&m.model===binding.model&&m.assembly===binding.assembly);const residues=mapping?.pairs.filter(p=>this.selectedFeatureIds.has(p.proteinResidueId)).map(p=>p.structureResidue)??[];if(residues.length)this.services.selectStructureRange(residues);this.services.notify(chosen.positions.length+' source-linked feature residues selected'+(residues.length?' · '+residues.length+' reviewed structural positions':' · no reviewed structural correspondence'));
 }
 private renderMappingTools(){

  const structure=this.services.getStructure(),box=el('section');box.innerHTML=`<h2>Reviewed structure correspondence</h2><p>Map the selected protein to a resolved structural chain. Missing segments and mismatches remain visible; this does not construct a new fold.</p><label class="field">Structural chain<select id="seq-map-chain">${(structure?.chains??[]).map(c=>`<option>${e(c)}</option>`).join('')}</select></label><p class="muted">Global sequence proposal: match +2, mismatch −1, linear gap −2. Review every retained pair.</p><button id="seq-map-propose">Propose correspondence</button><button id="seq-map-mutate">Construct substitutions from retained mapping</button><div id="seq-map-review"></div>`;this.panel.append(box);

  this.bind('#seq-map-mutate',async()=>{const state=this.requireCurrent(),binding=this.services.getStructure(),ids=new Set(state.residueIds),mapping=this.state.mappings.findLast(m=>m.reviewed&&m.pairs.some(p=>ids.has(p.proteinResidueId)));if(!binding||!mapping||mapping.sourceSha256!==binding.sourceSha256||mapping.model!==binding.model||mapping.assembly!==binding.assembly)throw new Error('Retain and review a mapping to the current structural branch first.');const aa:Record<string,string>={A:'ALA',R:'ARG',N:'ASN',D:'ASP',C:'CYS',Q:'GLN',E:'GLU',G:'GLY',H:'HIS',I:'ILE',L:'LEU',K:'LYS',M:'MET',F:'PHE',P:'PRO',S:'SER',T:'THR',W:'TRP',Y:'TYR',V:'VAL'};const changed=mapping.pairs.filter(p=>ids.has(p.proteinResidueId)&&p.expected!==p.observed);if(!changed.length)throw new Error('No substitutions in the retained mapping. Missing/unmapped segments are not modeled.');if(changed.length>32)throw new Error('Review at most 32 substitutions per scenario.');if(!confirm(changed.map(p=>p.structureResidue+': '+p.observed+' → '+p.expected).join('\n')+'\nConstruct these mapped substitutions as a separate molecular scenario? The retained backbone is not a new predicted fold.'))return;await this.services.mutateMapped(changed.map(p=>({residue:p.structureResidue,modification:'mutation:'+aa[p.expected]})));});
  this.bind('#seq-map-propose',async()=>{const state=this.requireCurrent(),binding=this.services.getStructure(),epoch=this.epoch;if(!binding)throw new Error('Import molecular coordinates before proposing a structural mapping.');const chain=this.value('seq-map-chain'),settings={match:2,mismatch:-1,gap:-2};const result=await this.services.compute('sequence-map',{text:binding.text,protein:state.sequence,chain,settings});if(epoch!==this.epoch||this.current()?.id!==state.id)throw new Error('The selected protein changed; the mapping proposal was discarded.');const review=this.panel.querySelector('#seq-map-review')!;review.innerHTML=`<p>${e(result.method)} · score ${result.score}${result.ambiguousBestAlignment?' · multiple equally scoring alignments; review ambiguity':''}</p><div class="table-scroll"><table><thead><tr><th>Retain</th><th>Protein</th><th>Structure</th><th>Identity</th></tr></thead><tbody>${result.pairs.map((p:any,i:number)=>`<tr><td><input type="checkbox" data-map-row="${i}" ${p.matches?'checked':''} aria-label="Retain protein ${p.position} to ${e(p.structureResidue)}"></td><td>${p.expected}${p.position}</td><td>${e(p.structureResidue)} · ${p.observed}</td><td>${p.matches?'Match':'Mismatch'}</td></tr>`).join('')}</tbody></table></div><label><input id="seq-map-confirm" type="checkbox"> I reviewed the retained correspondence and unresolved regions</label><button id="seq-map-accept">Retain reviewed mapping</button>`;

   this.bind('#seq-map-accept',()=>{if(!this.root.querySelector<HTMLInputElement>('#seq-map-confirm')!.checked)throw new Error('Review and confirm the mapping before retaining it.');if(this.current()?.id!==state.id)throw new Error('The mapping proposal belongs to a different protein state.');const now=this.services.getStructure();if(!now||now.sourceSha256!==binding.sourceSha256||now.model!==binding.model||now.assembly!==binding.assembly)throw new Error('Structural source/model/assembly changed; propose a fresh mapping.');const pairs=[...review.querySelectorAll<HTMLInputElement>('[data-map-row]:checked')].map(input=>{const p=result.pairs[Number(input.dataset.mapRow)];return {proteinResidueId:state.residueIds[p.position-1],position:p.position,structureResidue:p.structureResidue,expected:p.expected,observed:p.observed};});if(!pairs.length)throw new Error('Retain at least one reviewed pair.');this.commit({...this.state,mappings:[...this.state.mappings,{id:crypto.randomUUID(),proteinStateId:state.id,sourceSha256:binding.sourceSha256,model:binding.model,assembly:binding.assembly,chain,method:result.method,settings,reviewed:true,pairs}]});});

  });

 }

 private inspectSelectedRange(){const binding=this.services.getStructure(),mapping=this.state.mappings.findLast(m=>m.reviewed&&m.sourceSha256===binding?.sourceSha256&&m.model===binding.model&&m.assembly===binding.assembly&&m.pairs.some(p=>this.selectedFeatureIds.has(p.proteinResidueId)));const ids=mapping?.pairs.filter(p=>this.selectedFeatureIds.has(p.proteinResidueId)).map(p=>p.structureResidue)??[];if(ids.length)this.services.selectStructureRange(ids);}
